type LoadResult = { redirect: string } | { itemCount: number };

function loadCheckout(signedIn: boolean, itemCount: number): LoadResult {
  if (!signedIn) {
    return { redirect: "/login" };
  }
  if (itemCount <= 0) {
    return { redirect: "/cart" };
  }
  return { itemCount };
}
